def empty_authoring_week(week_number):
    """An unauthored week shell, in the shape save_module_authoring_structure expects."""
    return {
        'weekNumber': week_number,
        'title': f'Week {week_number}',
        'summary': '',
        'learningOutcomes': [],
        'components': [],
        'ksbMappings': [],
    }

week_holds_authored_content.source:
def week_holds_authored_content(week):
    """Whether a week holds anything somebody actually put there.

    An untouched week shell -- the thing a week-count change creates -- is a
    default title and nothing else. Everything past that is authored work.
    """
    if not isinstance(week, dict):
        return False
    if week.get('components') or week.get('ksbMappings') or week.get('learningOutcomes'):
        return True
    if clean_str(week.get('summary')):
        return True
    title = clean_str(week.get('title'))
    if not title:
        return False
    week_number = parse_int(week.get('weekNumber') or week.get('week_number'), 0)
    return normalise(title) != normalise(f'Week {week_number}')

attachment_session_count.source:
def attachment_session_count(item, weeks=None):
    """Resolve the session count for an attachment payload.

    `weeks` may arrive as an integer count or as a list of authored weeks, so the
    count is taken from sessionsNumber first, then an integer `weeks`, then the
    length of the resolved week structure.
    """
    item = item or {}
    explicit = parse_int(item.get('sessionsNumber'), 0)
    if explicit:
        return explicit
    weekly = module_weekly_schedule(item)
    if weekly:
        count = parse_int(item.get('weeks') or item.get('weeksNumber'), 0) or len(weeks or payload_week_list(item.get('weekStructure') or item.get('weeks')))
        return max(1, count) * len(weekly)
    raw_weeks = item.get('weeks')
    if not isinstance(raw_weeks, (list, tuple, dict)):
        counted = parse_int(raw_weeks, 0)
        if counted:
            return counted
    return len(weeks or payload_week_list(raw_weeks))

module_cohort_date_error.source:
def module_cohort_date_error(module_name, start_value, end_value, cohort):
    """Refuse a module whose dates fall outside its cohort's delivery window.

    Three ways out of the window, one message each: starting before the allowed
    soft-start month, starting after it has finished, and -- the case a
    generated session plan reaches on its own -- running past the end. Returns
    ``(message, field)`` or ``None``.
    """
    cohort_start, cohort_end = cohort_delivery_window(cohort)
    soft_start = module_soft_start_date(cohort_start) or cohort_start
    module_start = parse_date(start_value)
    module_end = parse_date(end_value)
    label = f'Module "{clean_str(module_name)}"' if clean_str(module_name) else 'The module'

    if module_start and soft_start and module_start < soft_start:
        return (
            f'{label} cannot start more than one month before the cohort start date ({format_date(cohort_start)}).',
            'startDate',
        )
    if module_start and cohort_end and module_start > cohort_end:
        return (
            f'{label} cannot start after the cohort end date ({format_date(cohort_end)}).',
            'startDate',
        )
    if module_end and cohort_end and module_end > cohort_end:
        return (
            f'{label} cannot finish after the cohort end date ({format_date(cohort_end)}). '
            f'It currently finishes {format_date(module_end)} -- move the start date earlier '
            f'or reduce the number of sessions.',
            'endDate',
        )
    return None

merge_partial_module_structure.source:
def merge_partial_module_structure(stored, payload):
    """Rebuild the whole module a full save would have sent, from a partial one.

    Module fields come from the payload alone -- as in a full save, where they
    come from the client and nowhere else. Weeks and components the author
    changed come from ``structureDelta``; everything else is the stored copy.
    The delta carries the order of every week and component, so moves,
    reorders and removals need no rows of their own.
    """
    delta = payload.get('structureDelta')
    if not isinstance(delta, dict):
        raise ModuleAuthoringValidationError([{'path': 'structureDelta', 'message': 'A partial save needs its changes.'}])
    stored_weeks = {clean_str(week.get('id')): week for week in (stored.get('weekStructure') or [])}
    stored_components = {
        clean_str(component.get('id')): component
        for week in stored_weeks.values()
        for component in (week.get('components') or [])
    }
    changed_weeks = delta.get('weeks') if isinstance(delta.get('weeks'), dict) else {}
    changed_components = delta.get('components') if isinstance(delta.get('components'), dict) else {}
    component_order = delta.get('componentOrder') if isinstance(delta.get('componentOrder'), dict) else {}
    week_order = delta.get('weekOrder') if isinstance(delta.get('weekOrder'), list) else []
    weeks = []
    for raw_week_id in week_order:
        week_id = clean_str(raw_week_id)
        source = changed_weeks.get(week_id) or stored_weeks.get(week_id)
        if not isinstance(source, dict):
            raise ModuleStructureDeltaConflict(f'Week {week_id} is not in the saved module.')
        components = []
        for raw_component_id in component_order.get(week_id) or []:
            component_id = clean_str(raw_component_id)
            component = changed_components.get(component_id) or stored_components.get(component_id)
            if not isinstance(component, dict):
                raise ModuleStructureDeltaConflict(f'Component {component_id} is not in the saved module.')
            components.append(component)
        weeks.append({**{key: value for key, value in source.items() if key != 'components'}, 'components': components})
    module_fields = {
        key: value for key, value in payload.items()
        if key not in {'saveMode', 'structureDelta', 'expectedRevision', 'expected_revision', 'weekStructure', 'weeks'}
    }
    return {**module_fields, 'weekStructure': weeks}

find_existing_authoring_catalogue_id_for.source:
def find_existing_authoring_catalogue_id_for_payload(payload):
    requested_catalogue_id = first_clean_payload_value(payload, 'catalogueId', 'moduleCatalogueId', 'module_catalogue_id')
    if requested_catalogue_id:
        resolved = resolve_authoring_catalogue_id(requested_catalogue_id)
        if resolved:
            return resolved

    # Standalone courses have no placement to disambiguate a shared title.
    # Only an explicit existing id can identify an existing free course.
    if payload.get('isFreeCourse') is True:
        return ''

    try:
        ensure_module_authoring_tables()
        title = first_clean_payload_value(payload, 'title', 'name')
        if not title:
            return ''

        programme_values = [
            payload.get('programmeId'),
            payload.get('programme_id'),
            payload.get('programmeName'),
            payload.get('programme'),
        ]
        cohort_values = [
            payload.get('cohortId'),
            payload.get('cohort_id'),
            payload.get('cohortName'),
            payload.get('cohort'),
        ]
        group_values = [
            payload.get('groupId'),
            payload.get('group_id'),
            payload.get('groupName'),
            payload.get('group'),
        ]
        component_counts = authoring_component_counts_by_catalogue()
        rows = sorted(
            authoring_fetch_all(AUTHORING_MODULES_TABLE, order_sql='updated_at desc, module_catalogue_id'),
            key=lambda row: (component_counts.get(clean_str(row.get('module_catalogue_id')), 0), row.get('updated_at') or ''),
            reverse=True,
        )
        for row in rows:
            if normalise(row.get('title')) != normalise(title):
                continue
            # A standalone course and an unplaced module may share a title.
            # Creation must never adopt the other kind's content or identity.
            if (row.get('source_type') == 'free_course') != (payload.get('isFreeCourse') is True):
                continue
            # An archived module is not "the same module" a create is asking
            # for. Adopting it handed a fresh copy the archived row's id, the
            # next save cleared the archive on the module row alone, and the
            # weeks archived with it stayed stamped with that id -- so the
            # module then ran with two sets of weeks.
            if module_withdrawn_on_its_own(row):
                continue
            if not identity_values_match_context([row.get('programme_id'), row.get('programme_name')], programme_values):
                continue
            if not identity_values_match_context([row.get('cohort_id'), row.get('cohort_name')], cohort_values):
                continue
            if not identity_values_match_context([row.get('group_id'), row.get('group_name')], group_values):
                continue
            return clean_str(row.get('module_catalogue_id'))
    except Exception:
        logger.debug('Unable to find existing authoring module for payload.', exc_info=True)
    return ''
